do $seed$
declare cid uuid;
begin
  select id into cid from public.courses where slug = 'spanish-2';
  if cid is null then raise exception 'Run the course file first'; end if;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 19, $j$Check 4.4: Health, the Pharmacy and Emergencies$j$, $j${"questions": [{"q": "Tengo dolor de cabeza means:", "options": ["I have a fever", "I have a headache", "I have a cold", "I am dizzy"]}, {"q": "Llame al 911 is a:", "options": ["Formal command", "Past tense", "Question", "Informal command"]}, {"q": "La receta is the:", "options": ["Prescription", "Pharmacy", "Nurse", "Pill"]}, {"q": "A church volunteer should:", "options": ["Diagnose illness", "Prescribe medicine", "Avoid helping", "Call a professional for serious needs"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.4: Health, the Pharmacy and Emergencies$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,0,0,3}'::int[], array[$j$Dolor de cabeza is headache.$j$,$j$Llame is the usted command of llamar.$j$,$j$Receta means prescription or recipe.$j$,$j$Volunteers comfort and call for help.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.4: Health, the Pharmacy and Emergencies$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 20, $j$Unit Quiz 4: Commands, Travel and Community$j$, $j${"questions": [{"q": "The usted command of comer is:", "options": ["Comes", "Comer", "Come", "Coma"]}, {"q": "The usted command of tener is:", "options": ["Tengues", "Tené", "Tiene", "Tenga"]}, {"q": "The affirmative tú command of venir is:", "options": ["Ven", "Vienes", "Venga", "Viene"]}, {"q": "The negative tú command of hablar is:", "options": ["No hables", "No hable", "No hablar", "No habla"]}, {"q": "Siga derecho means:", "options": ["Stop", "Turn right", "Keep going straight", "Cross the street"]}, {"q": "El pasaporte is a:", "options": ["Ticket", "Flight", "Passport", "Suitcase"]}, {"q": "Soy alérgico a means:", "options": ["I am angry at", "I am allergic to", "I am sick with", "I am tired of"]}, {"q": "A volunteer who sees a serious injury should:", "options": ["Call 911", "Wait a day", "Give medicine", "Ignore it"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 4: Commands, Travel and Community$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,3,0,0,2,2,1,0}'::int[], array[$j$Er verbs take a in the formal command.$j$,$j$Tengo gives tenga.$j$,$j$Ven is irregular.$j$,$j$Negative tú commands end in es for ar verbs.$j$,$j$Derecho means straight ahead.$j$,$j$Pasaporte means passport.$j$,$j$Alérgico a means allergic to.$j$,$j$Call for professional help.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 4: Commands, Travel and Community$j$ on conflict (item_id) do nothing;
end
$seed$;
